const pptxgen = require('pptxgenjs');

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'GitHub Trending Repos Snapshot: The Rise of AI Coding Agents & Claude Code Skills'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative background element
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 5.625,
    fill: { color: theme.primary },
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.15, h: 5.625,
    fill: { color: theme.secondary }
  });

  // Main Title
  slide.addText("GitHub Trending Repos Snapshot", {
    x: 0.8, y: 1.5, w: 8.5, h: 0.8,
    fontSize: 44, fontFace: "Arial Black",
    color: theme.bg, bold: true, align: "left", margin: 0
  });

  slide.addText("The Rise of AI Coding Agents & Claude Code Skills", {
    x: 0.8, y: 2.3, w: 8.5, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: theme.secondary, bold: true, align: "left", margin: 0
  });

  // Divider
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 3.2, w: 2, h: 0.05,
    fill: { color: theme.accent }
  });

  // Subtitle / Meta
  slide.addText("Based on OSSInsight's 10.6B+ GitHub events dataset", {
    x: 0.8, y: 3.5, w: 8.5, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.light, align: "left", margin: 0
  });

  slide.addText("April 2026", {
    x: 0.8, y: 3.9, w: 8.5, h: 0.4,
    fontSize: 16, fontFace: "Arial",
    color: theme.light, align: "left", margin: 0
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

const pptxgen = require('pptxgenjs');

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'OSSInsight Tracks 10.6 Billion GitHub Events in Real Time'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Arial Black",
    color: theme.primary, bold: true
  });

  // Divider
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 9, h: 0.02,
    fill: { color: theme.light }
  });

  // Body text
  slide.addText("OSSInsight is a free, real-time analytics platform providing deep insights into open-source repositories, developers, and organizations. The platform ranks trending repositories using a composite score:", {
    x: 0.5, y: 1.4, w: 9, h: 0.8,
    fontSize: 18, fontFace: "Arial",
    color: theme.primary, align: "left"
  });

  // Formula box
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 1.5, y: 2.3, w: 7, h: 0.8,
    fill: { color: theme.light },
    rectRadius: 0.1
  });

  slide.addText("Total Score = Stars score + Forks score + Base score", {
    x: 1.5, y: 2.3, w: 7, h: 0.8,
    fontSize: 20, fontFace: "Arial", bold: true,
    color: theme.secondary, align: "center", margin: 0
  });

  // Callout Numbers
  const metrics = [
    { label: "Total Events Tracked", value: "10.6B+" },
    { label: "Analysis Window", value: "24 Hours" },
    { label: "Trending Repos Analyzed", value: "Top 20" }
  ];

  metrics.forEach((m, i) => {
    const xPos = 1.0 + (i * 2.8);
    // Background card for metric
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: xPos, y: 3.5, w: 2.5, h: 1.2,
      fill: { color: theme.bg },
      line: { color: theme.light, width: 1 },
      rectRadius: 0.1
    });

    // Value
    slide.addText(m.value, {
      x: xPos, y: 3.6, w: 2.5, h: 0.6,
      fontSize: 32, fontFace: "Arial Black",
      color: theme.accent, bold: true, align: "center", margin: 0
    });

    // Label
    slide.addText(m.label, {
      x: xPos, y: 4.2, w: 2.5, h: 0.4,
      fontSize: 14, fontFace: "Arial",
      color: theme.primary, align: "center", margin: 0
    });
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

const pptxgen = require('pptxgenjs');

const slideConfig = {
  type: 'content',
  index: 3,
  title: 'hermes-agent Leads with 1,347 Stars — Top 5 Repos by Total Score'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Arial Black",
    color: theme.primary, bold: true
  });

  // Divider
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 9, h: 0.02,
    fill: { color: theme.light }
  });

  // Table Data
  const tableData = [
    [
      { text: "Rank", options: { bold: true, color: "FFFFFF", fill: { color: theme.secondary } } },
      { text: "Repository", options: { bold: true, color: "FFFFFF", fill: { color: theme.secondary } } },
      { text: "Stars", options: { bold: true, color: "FFFFFF", fill: { color: theme.secondary } } },
      { text: "Forks", options: { bold: true, color: "FFFFFF", fill: { color: theme.secondary } } },
      { text: "Pushes", options: { bold: true, color: "FFFFFF", fill: { color: theme.secondary } } },
