  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 9, h: 0.04,
    fill: { color: theme.secondary }
  });

  // Bullets
  const takeaways = [
    {
      title: "AI Agent Dominance",
      desc: "14 of the top 20 repos (70%) are AI coding agent tools, skills, or related resources — an unprecedented concentration."
    },
    {
      title: "Claude Code Ecosystem Explosion",
      desc: "At least 7 repos are specifically Claude Code skills, guides, or multi-tool switchers, showing rapid community formation."
    },
    {
      title: "Python Leadership, TypeScript Runner-up",
      desc: "Python powers 35% of trending repos (AI/ML core), while TypeScript (20%) drives agent UIs and developer experience layers."
    },
    {
      title: "Top-Heavy Community Engagement",
      desc: "hermes-agent attracted 78 PRs in 24 hours, but most repos below #8 show minimal collaborative activity (early-stage virality)."
    },
    {
      title: "Token Efficiency is a Priority",
      desc: "Multiple repos focus on reducing LLM token consumption, signaling cost-consciousness as AI coding tools scale."
    }
  ];

  takeaways.forEach((item, idx) => {
    const yPos = 1.6 + (idx * 0.7);

    // Checkmark shape (using a small rectangle and text instead of icon for simplicity without sharp/react-icons)
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: yPos + 0.05, w: 0.25, h: 0.25,
      fill: { color: theme.accent }
    });

    slide.addText("✓", {
      x: 0.5, y: yPos + 0.05, w: 0.25, h: 0.25,
      fontSize: 12, color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
    });

    slide.addText([
      { text: item.title + ": ", options: { bold: true, color: theme.secondary } },
      { text: item.desc, options: { color: theme.primary } }
    ], {
      x: 0.9, y: yPos, w: 8.5, h: 0.4,
      fontSize: 16, fontFace: "Arial", valign: "middle", margin: 0
    });
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
