const pptxgen = require('pptxgenjs');
const fs = require('fs');

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

// "Platinum White Gold" / "Tech Blue" hybrid - highly professional theme
const theme = {
  primary: "0a0a0a",
  secondary: "0070F3",
  accent: "D4AF37",
  light: "f5f5f5",
  bg: "ffffff"
};

for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: '../output/final_deck.pptx' })
  .then(() => {
    console.log('Presentation created at /app/output/final_deck.pptx');
  })
  .catch(err => {
    console.error('Error creating presentation:', err);
  });

